// Generated by vibelang from src/home/sessions/open.ts; the migrate flow writes it again with each batch.
export function shouldOpenSessionInBackground(input) {
    if (input.button === 1)
        return true;
    if (input.button !== 0)
        return false;
    if (input.shift || input.alt)
        return false;
    if (input.mac)
        return input.meta && !input.ctrl;
    return input.ctrl && !input.meta;
}
